export function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
}
export function safeMarkdownUrl(value) {
  try {
    if(typeof value!=='string'||/[\u0000-\u0020\u007f]/.test(value))return null;
    const url=new URL(value);
    return ['http:','https:','mailto:'].includes(url.protocol)?url.href:null;
  }catch{return null;}
}
const backtick=String.fromCharCode(96),maxDepth=32;
function runEnd(source,start,character=source[start]) {
  let end=start;while(source[end]===character)end++;return end;
}
function codeSpan(source,start) {
  const length=runEnd(source,start)-start;
  let position=start+length;
  while(position<source.length){
    const next=source.indexOf(backtick,position);if(next<0)return null;
    const end=runEnd(source,next);
    if(end-next===length){
      let content=source.slice(start+length,next).replaceAll('\n',' ');
      if(content.startsWith(' ')&&content.endsWith(' ')&&content.trim())content=content.slice(1,-1);
      return {content,end};
    }
    position=end;
  }
