  for(let position=0;position<source.length;position++){
    if(source[position]==='\\'){position++;continue;}
    if(skipCode&&source[position]===backtick){const code=codeSpan(source,position);if(code){position=code.end-1;continue;}}
    if(source[position]===opening)pending.push(position);
    else if(source[position]===closing&&pending.length)pairs.set(pending.pop(),position);
  }
  return pairs;
}
const unescapeText=value=>value.replace(/\\(.)/gs,'$1');
function readLink(source,start,brackets,parentheses) {
  const labelEnd=brackets.get(start);
  if(labelEnd===undefined||source[labelEnd+1]!=='(')return null;
  const end=parentheses.get(labelEnd+1);
  if(end===undefined||labelEnd-start>501)return null;
  return {label:source.slice(start+1,labelEnd),destination:unescapeText(source.slice(labelEnd+2,end)),raw:source.slice(start,end+1),end:end+1};
}
function formatEnd(source,start,marker,brackets,parentheses) {
  for(let position=start;position<source.length;position++){
    if(source[position]==='\\'){position++;continue;}
    if(source[position]===backtick){const code=codeSpan(source,position);if(code){position=code.end-1;continue;}}
    if(source[position]==='['){const link=readLink(source,position,brackets,parentheses);if(link){position=link.end-1;continue;}}
    if(source.startsWith(marker,position)&&runEnd(source,position)-position===marker.length&&!/\s/.test(source[position-1]))return position;
    if(source[position]===marker[0])position=runEnd(source,position)-1;
  }
