  const brackets=delimiterPairs(source,'[',']',true),parentheses=delimiterPairs(source,'(',')');
  let html='',position=0;
  while(position<source.length){
    const character=source[position],remaining=source.slice(position);
    if(character==='\\'&&position+1<source.length){html+=source[position+1]==='\n'?'<br>':escapeHtml(source[position+1]);position+=2;continue;}
    if(character===backtick){
      const code=codeSpan(source,position);
      if(code){html+='<code>'+escapeHtml(code.content)+'</code>';position=code.end;continue;}
      const end=runEnd(source,position);html+=escapeHtml(source.slice(position,end));position=end;continue;
    }
    if(character==='@'&&source[position+1]==='['){
      const reference=readLink(source,position+1,brackets,parentheses);
      if(reference&&reference.label.length<=120&&/^user:[^\s()]{1,128}$/.test(reference.destination)){
        const id=reference.destination.slice(5);mentions.push(id);
        html+='<span class="mention" data-user-id="'+escapeHtml(id)+'">@'+escapeHtml(unescapeText(reference.label))+'</span>';
        position=reference.end;continue;
      }
    }
    const direct=remaining.match(/^@\{([^}\s]{1,128})\}/),handle=remaining.match(/^@([A-Za-z0-9_.+%-]+(?:@[A-Za-z0-9.-]+\.[A-Za-z]{2,})?)/);
    if((direct||handle)&&(position===0||!/[\w@]/.test(source[position-1]))){
      const match=direct??handle;mentions.push(match[1]);html+='<span class="mention">@'+escapeHtml(match[1])+'</span>';position+=match[0].length;continue;
    }
    if(allowLinks&&character==='['){
      const link=readLink(source,position,brackets,parentheses);
      if(link){
        const url=safeMarkdownUrl(link.destination);
        html+=url?'<a href="'+escapeHtml(url)+'" rel="noopener noreferrer">'+inline(link.label,mentions,depth+1,false)+'</a>':escapeHtml(link.raw);
        position=link.end;continue;
      }
    }
    let formatted=false;
    for(const [marker,opening,closing] of [['***','<strong><em>','</em></strong>'],['___','<strong><em>','</em></strong>'],['**','<strong>','</strong>'],['__','<strong>','</strong>'],['~~','<del>','</del>'],['*','<em>','</em>'],['_','<em>','</em>']]){
      if(!remaining.startsWith(marker)||runEnd(source,position)-position!==marker.length||/\s/.test(source[position+marker.length]??' '))continue;
      if(marker[0]==='_'&&/[\w]/.test(source[position-1]??''))continue;
      const end=formatEnd(source,position+marker.length,marker,brackets,parentheses);
      if(end<=position+marker.length||marker[0]==='_'&&/\w/.test(source[end+marker.length]??''))continue;
      html+=opening+inline(source.slice(position+marker.length,end),mentions,depth+1,allowLinks)+closing;
      position=end+marker.length;formatted=true;break;
    }
    if(formatted)continue;
