}
function expandIndent(line) {
  let column=0,position=0;
  while(line[position]===' '||line[position]==='\t'){column+=line[position]==='\t'?4-column%4:1;position++;}
  return ' '.repeat(column)+line.slice(position);
}
function fenceStart(line) {
  const match=line.match(/^( {0,3})(\x60{3,}|~{3,})(.*)$/);
  if(!match||match[2][0]===backtick&&match[3].includes(backtick))return null;
  return {indent:match[1].length,character:match[2][0],length:match[2].length,info:match[3].trim()};
}
function fenceEnd(line,fence) {
  const value=line.replace(/^ {0,3}/,'');
  return value[0]===fence.character&&runEnd(value,0)>=fence.length&&!value.slice(runEnd(value,0)).trim();
}
function listMarker(line) {
  const match=line.match(/^( {0,3})([-+*]|\d{1,9}[.)])( +)(.*)$/);
  if(!match)return null;
  const padding=match[3].length>4?1:match[3].length;
  return {indent:match[1].length,ordered:/\d/.test(match[2]),number:parseInt(match[2],10),
    contentIndent:match[1].length+match[2].length+padding,content:match[3].slice(padding)+match[4]};
}
function startsBlock(line) {
  return !line.trim()||Boolean(fenceStart(line)||listMarker(line)||/^ {0,3}(?:#{1,6}\s|>|(?:-{3,}|\*{3,}|_{3,})\s*$)/.test(line));
}
function codeBlock(lines,language='') {
  return '<pre><code'+(language?' class="language-'+language+'"':'')+'>'+escapeHtml(lines.join('\n'))+'</code></pre>';
}
function listBlock(lines,start,mentions,depth) {
  const first=listMarker(lines[start]),items=[];
  let index=start,loose=false;
  while(index<lines.length){
    const marker=listMarker(lines[index]);
    if(!marker||marker.indent!==first.indent||marker.ordered!==first.ordered)break;
    const parts=[marker.content];let openFence=fenceStart(marker.content),lazy=!startsBlock(marker.content)&&!/^ {4}/.test(marker.content),blank=false;
    index++;
    while(index<lines.length){
      const line=lines[index],next=listMarker(line);
      if(next&&next.indent===first.indent)break;
      if(!line.trim()){parts.push('');blank=true;lazy=false;index++;continue;}
      const indent=line.length-line.trimStart().length;
      if(indent>=marker.contentIndent){
        const content=line.slice(marker.contentIndent);parts.push(content);
        if(openFence){if(fenceEnd(content,openFence))openFence=null;lazy=false;}
        else{openFence=fenceStart(content);lazy=!startsBlock(content)&&!/^ {4}/.test(content);}
        index++;continue;
      }
      if(lazy&&!startsBlock(line)&&indent<4){parts.push(line);index++;continue;}
      break;
    }
    while(parts.at(-1)==='')parts.pop();
    const next=listMarker(lines[index]??'');
    loose ||= parts.includes('')||blank&&Boolean(next&&next.indent===first.indent&&next.ordered===first.ordered);
    const task=parts[0]?.match(/^\[([ xX])\]\s+(.*)$/);
    if(task)parts[0]=task[2];
    items.push({blocks:parseBlocks(parts,mentions,depth+1),task});
  }
  const tag=first.ordered?'ol':'ul',startAttribute=first.ordered&&first.number!==1?' start="'+first.number+'"':'';
  const html=items.map(item=>{
    const checkbox=item.task?'<input type="checkbox" disabled'+(item.task[1].toLowerCase()==='x'?' checked':'')+' aria-label="'+(item.task[1]===' '?'Incomplete':'Complete')+' task"> ':'';
    const body=item.blocks.map(block=>!loose&&block.kind==='paragraph'?block.html.slice(3,-4):block.html).join('\n');
    return '<li>'+checkbox+body+'</li>';
