    const line=lines[index];
    if(!line.trim()){index++;continue;}
    const fence=fenceStart(line);
    if(fence){
      const code=[];index++;
      while(index<lines.length&&!fenceEnd(lines[index],fence)){
        let content=lines[index++];const indentation=content.length-content.trimStart().length;
        content=content.slice(Math.min(indentation,fence.indent));code.push(content);
      }
